import { SizingConfigs } from '@/types/config';
import { Format, imageFormats, videoFormats } from '@/utils/formats';
import type { Job, Task } from '@/types/job';
import type { MediaDimensions } from '@/types/mediaDimensions';
import { minDimension } from './mediaDimensions';

export const createJob = (
  file: File,
  requestedConfigNames: string[],
  configs: SizingConfigs,
): Promise<Job> => {
  return getMediumSize(file)
    .then((originalDimensions) => {
      const requestedDimensions: Record<string, MediaDimensions> = {};
      requestedConfigNames.forEach((configName) => {
        const config = configs[configName];
        let requestedDimension: MediaDimensions;
        if (config.sizingType === 'height') {
          requestedDimension = {
            height: config.height,
            width:
              (originalDimensions.width * config.height) /
              originalDimensions.height,
          };
        } else {
          let width: number;
          if (config.sizingType === 'percentage')
            width = config.screenWidth * (config.percentage / 100);
          else if (config.sizingType === 'width') width = config.width;
          else throw new Error('Invalid sizing type');
          requestedDimension = {
            width: width,
            height:
              (originalDimensions.height * width) / originalDimensions.width,
          };
        }
        requestedDimension.width = Math.round(requestedDimension.width);
        requestedDimension.height = Math.round(requestedDimension.height);
        requestedDimensions[configName] = minDimension(
          originalDimensions,
          requestedDimension,
        );
      });
      const requestedFormats: Format[] = file.type.startsWith('image/')
        ? [...imageFormats]
        : [...videoFormats, ...imageFormats];
      const tasks: Record<string, Partial<Record<Format, Task>>> = {};
      requestedConfigNames.forEach((configName) => {
        requestedFormats.forEach((format) => {
          if (!tasks[configName]) tasks[configName] = {};
          tasks[configName][format] = { status: 'waiting' };
        });
      });

      return {
        id: crypto.randomUUID(),
        originalFile: file,
        originalFileObjectURL: URL.createObjectURL(file),
        originalDimensions,
        requestedDimensions,
        requestedFormats,
        tasks,
      };
    })
    .catch((error) => {
      const errorMessage =
        'Failed to create job for file ' +
        file.name +
        ': ' +
        (error.message || String(error));
      console.error(errorMessage);
      return Promise.reject(errorMessage);
    });
};

export const jobIsIncomplete = (job: Job): boolean => {
  return jobTasksAsArray(job).some(
    (task) => task.status === 'running' || task.status === 'waiting',
  );
};

const jobTasksAsArray = (job: Job): Task[] => {
  return Object.values(job.tasks).flatMap((deviceTasks) =>
    Object.values(deviceTasks),
  );
};

export const jobIsRunning = (job: Job): boolean => {
  return jobTasksAsArray(job).some((task) => task.status === 'running');
};

export const jobProportionOfDoneTasks = (job: Job): number => {
  const tasksAsArray = jobTasksAsArray(job);
  const total = tasksAsArray.length;
  if (total === 0) return 1;
  const done = tasksAsArray.filter(
    (task) => task.status === 'completed' || task.status === 'errored',
  ).length;
  if (done >= total) return 1;
  return done / total;
};

function getMediumSize(file: File): Promise<MediaDimensions> {
  if (file.type.startsWith('image/')) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        const result = { width: img.width, height: img.height };
        URL.revokeObjectURL(img.src);
        resolve(result);
      };
      img.onerror = reject;
      const url = URL.createObjectURL(file);
      img.src = url;
    });
  }
  if (file.type.startsWith('video/')) {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = function () {
        const res = { width: video.videoWidth, height: video.videoHeight };
        URL.revokeObjectURL(video.src);
        resolve(res);
      };
      video.onerror = function (e) {
        reject(e);
      };
      video.src = URL.createObjectURL(file);
    });
  }
  throw new Error('unsupported mime type: ' + file.type);
}
